function showMessage(text, type){
  const old = document.getElementById('toastMsg'); if(old) old.remove();
  const div = document.createElement('div');
  div.id='toastMsg';
  div.className = 'toast' + (type?(' '+type):'');
  div.textContent = text;
  document.body.appendChild(div);
  setTimeout(()=>{ if(div.parentNode) div.remove(); }, 3500);
}
function speak(text){
  try{ window.speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text); u.lang='en-US'; u.rate=0.9; window.speechSynthesis.speak(u); }catch(e){}
}
function sanitize(s){ return (s||'').toString().trim().replace(/[\/\\\s'"]+/g,'_'); }

// ---- Supabase 기반 key-value 저장소 (SUPABASE_URL / SUPABASE_ANON_KEY는 config.js에서 정의) ----
const sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

async function storeSet(key, value){
  try{
    const { error } = await sb.from('kv_store').upsert({ key, value, updated_at: new Date().toISOString() });
    if(error){ console.error(error); return null; }
    return true;
  }catch(e){ console.error(e); return null; }
}
async function storeGet(key){
  try{
    const { data, error } = await sb.from('kv_store').select('value').eq('key', key).maybeSingle();
    if(error){ console.error(error); return null; }
    return data ? data.value : null;
  }catch(e){ console.error(e); return null; }
}
async function storeList(prefix){
  try{
    const { data, error } = await sb.from('kv_store').select('key').like('key', prefix+'%');
    if(error){ console.error(error); return []; }
    return data ? data.map(r=>r.key) : [];
  }catch(e){ console.error(e); return []; }
}
async function storeDelete(key){
  try{
    const { error } = await sb.from('kv_store').delete().eq('key', key);
    if(error){ console.error(error); return null; }
    return true;
  }catch(e){ console.error(e); return null; }
}
function postKey(cls,num,name){ return `hero_post_${sanitize(cls)}_${sanitize(num)}_${sanitize(name)}`; }
function usedKey(cls){ return `hero_used_${sanitize(cls)}`; }
function escapeHtml(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function greetingFor(name){
  let h=0; for(const ch of (name||'x')) h += ch.charCodeAt(0);
  return h%2===0 ? 'Hello' : 'Hi';
}

function pickCard(canSentences, usedIds){
  const text = canSentences.join(' ').toLowerCase();
  let pool = CARDS.filter(c=>!usedIds.includes(c.id));
  if(pool.length===0){ usedIds=[]; pool=CARDS.slice(); }
  const weighted=[];
  pool.forEach(c=>{
    let score=0;
    c.tags.forEach(t=>{ if(new RegExp('\\b'+t+'\\b').test(text)) score++; });
    const weight = score>0 ? score*3+1 : 1;
    for(let i=0;i<weight;i++) weighted.push(c);
  });
  const chosen = weighted[Math.floor(Math.random()*weighted.length)];
  return {chosen, newUsed: usedIds.concat([chosen.id])};
}

const app = document.getElementById('app');
function render(){
  if(state.screen==='entry') return renderEntry();
  if(state.screen==='create') return renderCreate();
  if(state.screen==='reveal') return renderReveal();
  if(state.screen==='board') return renderBoard();
  if(state.screen==='teacherLogin') return renderTeacherLogin();
  if(state.screen==='teacherDash') return renderTeacherDash();
}

