  function abilityRow(i, kind, prefixLabel, prefixColor){
    return `<div class="ability-row"><span class="ability-prefix" style="${prefixColor?('background:'+prefixColor+';'):''}">${prefixLabel}</span>
    <input type="text" data-i="${i}" data-kind="${kind}" class="abilityInput" placeholder="" value="${escapeHtml(kind==='can'?state.canList[i]:state.cantList[i])}"></div>`;
  }
  const canRows=document.getElementById('canRows');
  canRows.innerHTML = `<div class="mini-label">&#9989; 필수 단어를 꼭 넣어서 써보세요 (2칸)</div>`
    + abilityRow(0,'can','I can')
