    const q=query.trim().toLowerCase();
    const results = PHRASES.filter(p=> p.ko.includes(query.trim()) || p.en.toLowerCase().includes(q));
    if(results.length===0){ box.innerHTML=`<div class="empty-search">검색 결과가 없어요. 선생님께 물어보세요!</div>`; return; }
